import { useEffect, useState } from 'react';
import { ChevronDown } from 'lucide-react';
import { API_ORIGIN } from '../../config';

type View = 'orders' | 'inventory' | 'payouts';
type RecordValue = Record<string, any>;
const headers = () => ({ Authorization: `Bearer ${localStorage.getItem('token') || ''}`, 'Content-Type': 'application/json' });
const request = async (path: string, options: RequestInit = {}) => { const response = await fetch(`${API_ORIGIN}${path}`, { ...options, headers: { ...headers(), ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'Request failed'); return data; };
const card = 'min-w-0 rounded-2xl border border-neutral-200 bg-white p-4 shadow-sm sm:p-5';
const button = 'rounded-xl bg-lime-600 px-4 py-2.5 font-bold text-white hover:bg-lime-700 disabled:opacity-60';

const VendorOperations = ({ view }: { view: View }) => {
  const [rows, setRows] = useState<RecordValue[]>([]); const [products, setProducts] = useState<RecordValue[]>([]); const [payments, setPayments] = useState<RecordValue>({}); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const [payoutMethod, setPayoutMethod] = useState('upi'); const [payoutMethodOpen, setPayoutMethodOpen] = useState(false);
  const load = async () => { setMessage(''); try { if (view === 'orders') setRows(await request('/partner/vendor/orders')); if (view === 'inventory') { const [productData, history] = await Promise.all([request('/partner/vendor/products'), request('/marketplace/vendor/inventory')]); setProducts(productData); setRows(history); } if (view === 'payouts') { const [paymentData, payouts] = await Promise.all([request('/partner/vendor/payments'), request('/partner/vendor/payout-requests')]); setPayments(paymentData); setRows(payouts); } } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to load data'); } };
  useEffect(() => { load(); }, [view]);
  useEffect(() => { if (payments.payoutProfile?.method) setPayoutMethod(payments.payoutProfile.method); }, [payments]);
  const updateOrder = async (id: number, status: string) => { setBusy(true); try { await request(`/partner/vendor/orders/${id}/status`, { method: 'PUT', body: JSON.stringify({ status }) }); setMessage('Order status updated.'); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to update order'); } finally { setBusy(false); } };
  const adjustInventory = async (id: number, quantity: number) => { setBusy(true); try { await request(`/marketplace/vendor/products/${id}/inventory-adjust`, { method: 'POST', body: JSON.stringify({ quantity }) }); setMessage('Stock adjusted.'); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to adjust stock'); } finally { setBusy(false); } };
  const savePayment = async (form: HTMLFormElement) => { setBusy(true); try { const data = new FormData(form); await request('/partner/vendor/payment-profile', { method: 'PUT', body: JSON.stringify(Object.fromEntries(data)) }); setMessage('Payout profile saved.'); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to save payout profile'); } finally { setBusy(false); } };
  const requestPayout = async (form: HTMLFormElement) => { setBusy(true); try { const data = new FormData(form); await request('/partner/vendor/payout-requests', { method: 'POST', body: JSON.stringify({ amount: Number(data.get('amount')) }) }); setMessage('Payout request submitted.'); form.reset(); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to request payout'); } finally { setBusy(false); } };
  const title = view === 'orders' ? 'Vendor orders' : view === 'inventory' ? 'Inventory & stock history' : 'Payouts';
  return <section className="mx-auto max-w-6xl"><div className="mb-6 flex flex-wrap items-center justify-between gap-3"><div><h1 className="text-2xl font-bold">{title}</h1><p className="mt-1 text-neutral-500">{view === 'orders' ? 'Review customer orders and keep customers updated.' : view === 'inventory' ? 'Manage current stock and review every adjustment.' : 'Manage payout details and request settlements.'}</p></div><button type="button" onClick={load} disabled={busy} className={button}>Refresh</button></div>{message ? <p className="mb-5 rounded-xl bg-lime-50 px-4 py-3 font-medium text-lime-800">{message}</p> : null}
    {view === 'orders' ? <div className="grid gap-4">{rows.length ? rows.map((order) => { const next = order.status === 'pending' ? 'processing' : order.status === 'processing' ? 'completed' : ''; let items: RecordValue[] = []; try { items = JSON.parse(order.items || '[]'); } catch { /* malformed legacy data */ } return <article key={order.id} className={card}><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold">Order #{order.id}</h2><p className="text-sm text-neutral-500">{order.customerName} · {order.email} · {order.phone || 'No phone'}</p></div><b className="text-lime-700">Rs. {order.total}</b></div><p className="mt-3 text-sm text-neutral-600"><b>Delivery address:</b> {order.shippingAddress || order.billingAddress || 'Not available'}</p><div className="mt-3 rounded-xl bg-neutral-50 p-3 text-sm">{items.length ? items.map((item, index) => <p key={index}>{item.name || 'Product'} × {item.quantity || 1}</p>) : 'Order items unavailable'}</div><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><span className="rounded-full bg-amber-100 px-3 py-1 text-sm font-bold capitalize text-amber-800">{order.status || 'pending'}</span>{next ? <button disabled={busy} type="button" className={button} onClick={() => updateOrder(order.id, next)}>{next === 'processing' ? 'Start processing' : 'Mark completed'}</button> : null}</div></article>; }) : <Empty text="No vendor orders yet." />}</div> : null}
    {view === 'inventory' ? <><div className="grid gap-4 md:grid-cols-2">{products.map((product) => <article key={product.id} className={card}><div className="flex items-center justify-between gap-3"><div><h2 className="font-bold">{product.name}</h2><p className="text-sm text-neutral-500">Current stock: {product.stockQuantity || 0}</p></div><div className="flex gap-2"><button disabled={busy} onClick={() => adjustInventory(product.id, -1)} className="rounded-lg border border-neutral-300 px-3 py-2 font-bold">−1</button><button disabled={busy} onClick={() => adjustInventory(product.id, 1)} className="rounded-lg bg-lime-600 px-3 py-2 font-bold text-white">+1</button></div></div></article>)}</div><h2 className="mb-3 mt-7 text-lg font-bold">Adjustment history</h2><div className="grid gap-3">{rows.length ? rows.map((row) => <div key={row.id} className={card}><b>{row.type || 'Adjustment'}</b><p className="mt-1 text-sm text-neutral-600">Stock: {row.previousStock} → {row.newStock} · Quantity: {row.quantity}</p><p className="mt-1 text-xs text-neutral-400">{row.createdAt ? new Date(row.createdAt).toLocaleString() : ''}</p></div>) : <Empty text="No inventory adjustments yet." />}</div></> : null}
    {view === 'payouts' ? <><div className="mb-5 grid gap-4 sm:grid-cols-2"><div className={card}><p className="text-sm text-neutral-500">Available to withdraw</p><b className="mt-2 block text-3xl text-lime-700">Rs. {payments.availableAmount || 0}</b></div><div className={card}><p className="text-sm text-neutral-500">Total earned</p><b className="mt-2 block text-3xl">Rs. {payments.earnedAmount || 0}</b></div></div><form className={card} onSubmit={(event) => { event.preventDefault(); savePayment(event.currentTarget); }}><h2 className="font-bold">Payout details</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="relative min-w-0"><input type="hidden" name="method" value={payoutMethod} /><button type="button" aria-expanded={payoutMethodOpen} onClick={() => setPayoutMethodOpen((open) => !open)} className="flex w-full items-center justify-between gap-3 rounded-xl border border-neutral-300 bg-white px-3 py-2.5 text-left"><span>{payoutMethod === 'bank' ? 'Bank account' : 'UPI'}</span><ChevronDown size={17} className={`shrink-0 transition-transform ${payoutMethodOpen ? 'rotate-180' : ''}`} /></button>{payoutMethodOpen ? <div role="listbox" className="absolute left-0 top-full z-30 mt-1 w-full overflow-hidden rounded-xl border border-neutral-200 bg-white py-1 shadow-lg"><button type="button" role="option" aria-selected={payoutMethod === 'upi'} onClick={() => { setPayoutMethod('upi'); setPayoutMethodOpen(false); }} className={`block w-full px-3 py-2 text-left text-sm hover:bg-lime-50 ${payoutMethod === 'upi' ? 'bg-lime-50 font-semibold text-lime-800' : ''}`}>UPI</button><button type="button" role="option" aria-selected={payoutMethod === 'bank'} onClick={() => { setPayoutMethod('bank'); setPayoutMethodOpen(false); }} className={`block w-full px-3 py-2 text-left text-sm hover:bg-lime-50 ${payoutMethod === 'bank' ? 'bg-lime-50 font-semibold text-lime-800' : ''}`}>Bank account</button></div> : null}</div><input name="upi" defaultValue={payments.payoutProfile?.upi || ''} placeholder="UPI ID" className="w-full min-w-0 rounded-xl border border-neutral-300 px-3 py-2.5" /><input name="accountName" defaultValue={payments.payoutProfile?.accountName || ''} placeholder="Account holder name" className="w-full min-w-0 rounded-xl border border-neutral-300 px-3 py-2.5" /><input name="accountNumber" defaultValue={payments.payoutProfile?.accountNumber || ''} placeholder="Account number" className="w-full min-w-0 rounded-xl border border-neutral-300 px-3 py-2.5" /><input name="ifsc" defaultValue={payments.payoutProfile?.ifsc || ''} placeholder="IFSC code" className="w-full min-w-0 rounded-xl border border-neutral-300 px-3 py-2.5" /></div><button disabled={busy} className={`${button} mt-4`}>Save payout details</button></form><form className={`${card} mt-5 flex flex-wrap items-end gap-3`} onSubmit={(event) => { event.preventDefault(); requestPayout(event.currentTarget); }}><label className="w-full flex-1 text-sm font-bold sm:w-auto">Amount<input required min="1" name="amount" type="number" className="mt-1 block w-full rounded-xl border border-neutral-300 px-3 py-2.5" /></label><button disabled={busy} className={`${button} w-full sm:w-auto`}>Request payout</button></form><h2 className="mb-3 mt-7 text-lg font-bold">Payout requests</h2><div className="grid gap-3">{rows.length ? rows.map((row) => <div key={row.id} className={card}><b>Rs. {row.amount}</b><span className="ml-3 rounded-full bg-neutral-100 px-3 py-1 text-sm font-semibold capitalize">{row.status}</span><p className="mt-2 text-sm text-neutral-500">{row.createdAt ? new Date(row.createdAt).toLocaleString() : ''}</p></div>) : <Empty text="No payout requests yet." />}</div></> : null}</section>;
};

const Empty = ({ text }: { text: string }) => <div className="rounded-2xl border border-dashed border-neutral-300 p-8 text-center text-neutral-500">{text}</div>;
export default VendorOperations;
